 readonly Stack<IEnumerator> steps=new Stack<IEnumerator>();readonly List<string> lines=new List<string>();readonly Dictionary<string,string> preferences=new Dictionary<string,string>();string folder;bool done,restored;int errors;CheeseMatch cheese;CurlingMatch curling;KeepawayMatch keep;
 void Start(){folder=LWS.TruckSports.SportsEvidencePaths.Folder("FocusedEvidence");Directory.CreateDirectory(folder);Application.logMessageReceived+=Log;steps.Push(Run());}
 void Log(string message,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;lines.Add("ERROR "+message);}}
 void Check(bool good,string label){lines.Add((good?"PASS ":"FAIL ")+label);if(!good)errors++;File.WriteAllLines(folder+"/progress.txt",lines);}
