 for(int weather=0;weather<3;weather++){int seed=0;for(;seed<100;seed++){cheese.weather.Select(seed);if((int)cheese.weather.Kind==weather)break;}truck.ResetTruck(CheeseRules.Surface(0,220,.65f),Quaternion.identity);truck.Release();truck.command=Vector2.zero;yield return Delay(1.2f);var begin=truck.body.position;truck.command=Vector2.up;yield return Delay(3.5f);Check(truck.BottomBlend>.99f&&truck.Grounded&&(truck.body.position-begin).magnitude>4,"bottom accelerates from rest under "+cheese.weather.Kind);Note("CHEESE rest weather="+cheese.weather.Kind+" distance="+(truck.body.position-begin).magnitude+" speed="+truck.body.linearVelocity.magnitude+" control="+truck.GroundControl);truck.command=Vector2.down;yield return Delay(5);Check(Vector3.Dot(truck.body.linearVelocity,truck.transform.forward)<-.5f,"opposite throttle brakes and reverses under "+cheese.weather.Kind);truck.command=new Vector2(.8f,-.8f);var yaw=truck.body.rotation;yield return Delay(2.5f);Check(Quaternion.Angle(yaw,truck.body.rotation)>25,"low-speed reverse steering under "+cheese.weather.Kind);}
 truck.ResetTruck(CheeseRules.Surface(0,235,2.4f),Quaternion.Euler(0,90,0));truck.Release();truck.body.linearVelocity=Vector3.forward*8;truck.command=Vector2.zero;yield return Delay(.2f);Check(truck.body.linearVelocity.z>6,"sideways airborne landing retains initial world momentum");yield return Delay(1.5f);truck.command=new Vector2(-.8f,.8f);yield return Delay(3.5f);Check(truck.GroundControl>.5f&&truck.body.linearVelocity.magnitude>1,"sideways landing regains useful steering/drive");cheese.weather.Select(0);truck.ResetTruck(CheeseRules.Surface(0,185,.65f),Quaternion.identity);truck.Release();truck.command=Vector2.zero;yield return Delay(1.2f);cheese.Explode(truck.body.position-Vector3.forward*3);float blastAt=Time.realtimeSinceStartup;for(int sample=0;sample<14;sample++){yield return Delay(1);Note("CHEESE BLAST t="+(Time.realtimeSinceStartup-blastAt)+" p="+truck.body.position+" speed="+truck.body.linearVelocity.magnitude+" disabled="+truck.DisabledFor+" up="+Vector3.Dot(truck.transform.up,Vector3.up)+" grounded="+truck.Grounded+" recoveries="+truck.Recoveries);if(truck.DisabledFor<=0&&truck.Grounded&&Vector3.Dot(truck.transform.up,Vector3.up)>.5f)break;}truck.command=Vector2.up;yield return Delay(2);Check(truck.DisabledFor<=0&&truck.body.linearVelocity.magnitude>1,"fresh centered explosion fixture clears control loss and drives again");cheese.enabled=true;cheese.ChangeSetup();}
 IEnumerator Curling(){SportsNavigation.LoadSport(SportsNavigation.Curling);yield return Delay(.8f);curling=FindAnyObjectByType<CurlingMatch>();Protect(curling.PreferenceKey);curling.teamA=curling.teamB=1;curling.setup.players[0].source=curling.setup.players[1].source=BowlingSource.Keyboard;Check(curling.StartMatch(),"Curling bank physical fixture starts");var stone=curling.Current;stone.truck.body.position=new Vector3(0,.38f,43);stone.truck.body.linearVelocity=new Vector3(9,0,.25f);yield return Wait(()=>curling.Phase==CurlingPhase.Slide,2,"committed bank slide");float prior=stone.truck.body.linearVelocity.x;int rebounds=0;float peak=0,end=Time.realtimeSinceStartup+35;while(curling.Delivery==0&&Time.realtimeSinceStartup<end){float vx=stone.truck.body.linearVelocity.x;if(Mathf.Abs(vx)>.2f&&Mathf.Abs(prior)>.2f&&Mathf.Sign(vx)!=Mathf.Sign(prior))rebounds++;if(Mathf.Abs(vx)>.2f)prior=vx;peak=Mathf.Max(peak,stone.truck.body.linearVelocity.magnitude);yield return null;}Check(rebounds>=2,"actual angled shot rebounds repeatedly off both walls");Check(stone.InPlay&&curling.Delivery==1,"legal bank remains in play and eventually settles");Check(peak<=9.3f,"physical banks do not add speed");Note("CURL bank rebounds="+rebounds+" peak="+peak+" resting="+stone.truck.body.position);
 yield return Wait(()=>curling.Phase==CurlingPhase.Approach,4,"second curling delivery");stone.Restore(new Vector3(4.1f,.38f,46),Quaternion.identity,false,false);typeof(CurlingMatch).GetMethod("BeginDelivery",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(curling,null);var delivered=curling.Current;delivered.truck.body.position=new Vector3(4,.38f,36);delivered.truck.body.linearVelocity=new Vector3(6,0,16);int violations=curling.GuardViolations;yield return Wait(()=>curling.Delivery>=2,55,"bank guard takeout resolves");Check(curling.PhysicalContacts>0,"bank takeout physically contacts the prior guard");Note("CURL guard protected="+CurlingRules.Guard(new Vector3(4.1f,.38f,46),false)+" violations="+curling.GuardViolations+" priorInPlay="+stone.InPlay+" priorPosition="+stone.truck.body.position+" activeInPlay="+delivered.InPlay);Check(curling.GuardViolations==violations+1&&stone.InPlay&&(stone.truck.body.position-new Vector3(4.1f,.38f,46)).magnitude<.05f&&!delivered.InPlay,"illegal bank guard removal restores the prior layout");curling.SetupScreen();}
 IEnumerator Keepaway(){SportsNavigation.LoadSport(SportsNavigation.Keepaway);yield return Delay(.8f);keep=FindAnyObjectByType<KeepawayMatch>();Protect(keep.PreferenceKey);Protect("Keepaway.Chaos.v1");keep.setup.count=4;keep.option=0;keep.weatherChoice=1;for(int i=0;i<4;i++)keep.setup.players[i].source=BowlingSource.Keyboard;Check(keep.StartMatch(),"Keepaway four-truck collision fixture starts");foreach(var item in keep.chaosField.sheep)item.Dormant();for(int i=0;i<4;i++)keep.trucks[i].Prepare(new Vector3(i%2==0?-27:27,.48f,i<2?-12:12),Quaternion.identity);keep.trucks[0].Prepare(new Vector3(0,.48f,-4),Quaternion.identity);keep.trucks[0].body.linearVelocity=Vector3.forward*7;yield return Wait(()=>keep.Carrier==0,4,"actual neutral pickup");Check(keep.Pickups==1&&keep.ball.isKinematic,"one physical ball pickup");keep.trucks[0].Prepare(new Vector3(0,.48f,0),Quaternion.identity);keep.trucks[1].Prepare(new Vector3(0,.48f,-7),Quaternion.identity);yield return Delay(.9f);keep.trucks[1].body.linearVelocity=Vector3.forward*8;yield return Wait(()=>keep.Carrier==1,4,"actual collision steal");Check(keep.Steals==1&&keep.Blasts==1&&!keep.alive[0]&&keep.alive[1],"atomic transfer before former-carrier blast; thief survives");keep.HazardBlast(keep.trucks[1].body.position);Check(keep.Carrier==-1&&!keep.alive[1]&&!keep.ball.isKinematic&&FindObjectsByType<KeepawayBall>().Length==1,"hazard carrier destruction drops exactly one neutral ball");float score=keep.possession[1];yield return Delay(.3f);Check(keep.possession[1]==score,"destroyed carrier stops accumulating possession");yield return Wait(()=>keep.alive[0],4,"protected respawn");Check(!keep.CanAttack(0),"respawn shield cannot steal");keep.SetupScreen();
 keep.StartMatch();keep.enabled=false;foreach(var item in keep.chaosField.sheep)item.Dormant();for(int i=1;i<4;i++)keep.trucks[i].Park(new Vector3(0,-5,0));keep.ball.isKinematic=true;keep.ballShape.enabled=false;
 for(int corner=0;corner<4;corner++){float sx=corner%2==0?-1:1,sz=corner<2?-1:1;var truck=keep.trucks[0];var start=new Vector3(sx*27,.48f,sz*14);truck.Prepare(start,Quaternion.Euler(0,sx*90,0));truck.Power(false);truck.body.linearVelocity=new Vector3(sx*6,0,sz);yield return Delay(3);var end=truck.body.position;Check(KeepawayBoundary.Contains(end,-.8f)&&(end-start).magnitude>1.2f,"actual truck glances around sealed rounded corner "+corner);Note("KEEP CORNER "+corner+" start="+start+" end="+end+" speed="+truck.body.linearVelocity.magnitude);}
 keep.enabled=true;keep.SetupScreen();
 for(int preset=1;preset<=5;preset++){keep.weatherChoice=preset;for(int i=0;i<4;i++){keep.setup.players[i].source=BowlingSource.AI;keep.setup.players[i].difficulty=(BowlingDifficulty)(i%3);}Check(keep.StartMatch(),"AI weather setup "+preset);Check(keep.chaosField.ConnectedCells>370,"connected navigable layout "+preset);if(preset<5){yield return Delay(2.5f);keep.SetupScreen();continue;}Time.timeScale=3;yield return Wait(()=>keep.Finished,240,"full four-AI chaos match");Check(keep.Winner>=0&&keep.possession[keep.Winner]==30,"AI chaos match reaches exact possession target");Check(keep.Steals>0&&keep.Blasts>=keep.Steals,"natural physical steals and hazards coexist");Note("KEEP winner="+keep.Winner+" steals="+keep.Steals+" blasts="+keep.Blasts+" chains="+keep.chaosField.Chains+" scores="+keep.Standings);Time.timeScale=1;keep.SetupScreen();}
